program.compute:
options = read('/input/options')
ids = [r['id'] for r in options]
candidates = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(ids, k):
        selection = list(group)
        if valid(selection):
            candidates = candidates + [selection]
            break
    if candidates:
        break
result = candidates[0] if candidates else []

program.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', read('/output/selection'))
elif status('report') == 'sent':
    pass
else:
    pass
if exists('/tmp/cache'):
    delete('/tmp/cache')

